-- Version 2 adds authenticated demo conversations without rebuilding version 1 data.
-- The raw random bearer token is returned to the browser, while only token_hash is
-- stored here. conv_id is generated by the server and belongs to exactly one session.
-- message_count persists usage. active_request identifies unfinished work; lease_until
-- is a UTC-second deadline, and claim_id identifies the worker attempt holding it.
CREATE TABLE customer_sessions (
    token_hash TEXT PRIMARY KEY, sandbox_id TEXT NOT NULL, customer_id TEXT NOT NULL,
    conv_id TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL,
    peer_hash TEXT NOT NULL, message_count INTEGER NOT NULL DEFAULT 0,
    active_request TEXT, lease_until INTEGER NOT NULL DEFAULT 0, claim_id TEXT,
    FOREIGN KEY (sandbox_id, customer_id) REFERENCES customers(sandbox_id, id) ON DELETE CASCADE
);
-- This lookup supports per-peer creation limits; a reverse proxy can make visitors
-- share one peer address. A hash is not a guarantee that IP information is anonymous.
CREATE INDEX sessions_peer ON customer_sessions(peer_hash, created_at);
-- One row per customer message. Reusing request_id with the same fingerprint replays
-- saved work. plan_json freezes the extracted intent before business effects run;
-- response_json records the final reply for a retry after a lost network response.
-- A foreign key ties requests to a session; deleting the session deletes its requests.
CREATE TABLE customer_requests (
    token_hash TEXT NOT NULL REFERENCES customer_sessions(token_hash) ON DELETE CASCADE,
    request_id TEXT NOT NULL, message TEXT NOT NULL, fingerprint TEXT NOT NULL,
    plan_json TEXT, response_json TEXT, created_at INTEGER NOT NULL,
    PRIMARY KEY (token_hash, request_id)
);
